using System;
using UnityEngine;

namespace Masar.Vehicles
{
    /// <summary>
    /// The cars the player can choose from. Generated by the editor (ImportedCarBuilder) into
    /// Resources, so every listed prefab is included in builds. Entry 0 is always the
    /// procedural test sedan, which exists on every machine.
    /// </summary>
    public sealed class CarCatalog : ScriptableObject
    {
        public const string ResourceName = "MasarCarCatalog";

        [Serializable]
        public class Entry
        {
            public string id;
            public string displayName;
            [Tooltip("One line shown under the name: class, drivetrain, power.")]
            public string summary;
            [Tooltip("Direct reference: only for cars that are in memory anyway (the scene's test sedan).")]
            public GameObject prefab;
            [Tooltip("Resources path of the prefab, loaded only when this car is chosen, so unchosen cars cost no memory.")]
            public string resourcePath;
            public Texture2D thumbnail;
            [Tooltip("Credit text required by the model's license.")]
            public string credit;
            public string license;
            [Tooltip("Shown in the selector when the model has a licensing caveat.")]
            public string warning;
            public int triangles;
            public bool hasInterior;

            public bool IsAvailable => prefab != null || !string.IsNullOrEmpty(resourcePath);

            public GameObject LoadPrefab() => prefab != null ? prefab : Resources.Load<GameObject>(resourcePath);
        }

        public Entry[] cars = Array.Empty<Entry>();

        private static CarCatalog s_Instance;

        public static CarCatalog Instance
        {
            get
            {
                if (s_Instance == null) s_Instance = Resources.Load<CarCatalog>(ResourceName);
                return s_Instance;
            }
        }

        public Entry Find(string id)
        {
            if (cars == null) return null;
            foreach (var c in cars) if (c != null && c.IsAvailable && c.id == id) return c;
            return null;
        }

        /// <summary>The selected car, or the first available one.</summary>
        public Entry FindOrDefault(string id)
        {
            var e = Find(id);
            if (e != null) return e;
            if (cars == null) return null;
            foreach (var c in cars) if (c != null && c.IsAvailable) return c;
            return null;
        }
    }
}
